def mse(preds, truths):
    total = 0
    for p, t in zip(preds, truths):
        total += (p - t) ** 2
    return total / len(preds)

print(mse([3.0, 5.0], [3.0, 5.0]))    # 0.0
print(mse([3.5, 5.0], [3.0, 5.0]))    # 0.125
print(mse([5.0, 5.0], [3.0, 5.0]))    # 2.0

# The decision tree
def choose_loss(task):
    if task == "regression":
        return "mse"    # predicting a number
    elif task == "binary_classification":
        return "binary_cross_entropy"
    elif task == "multi_class_classification":
        return "categorical_cross_entropy"
    else:
        raise ValueError("task not recognised")

print(choose_loss("regression"))            # mse
print(choose_loss("multi_class_classification"))  # categorical_cross_entropy

