import math

def categorical_cross_entropy(p_correct):
    return -math.log(p_correct)

def mean_squared_error(preds, truths):
    total = 0
    for p, t in zip(preds, truths):
        total += (p - t) ** 2
    return total / len(preds)

# Classification example
print("CE:", round(categorical_cross_entropy(0.8), 3))   # ~0.223

# Regression example
print("MSE:", round(mean_squared_error([2.9, 3.1], [3.0, 3.0]), 3))   # 0.01

